package mvvm_excercises.viewmodel;

import javafx.beans.property.ObjectProperty;
import javafx.beans.property.SimpleObjectProperty;
import javafx.beans.property.SimpleStringProperty;
import javafx.beans.property.StringProperty;

/**
 * Represents a single row in the exercises table.
 */
public class SimpleExerciseViewModel {

    private final StringProperty number    = new SimpleStringProperty();
    private final StringProperty topic     = new SimpleStringProperty();
    private final ObjectProperty<Boolean> completed = new SimpleObjectProperty<>();

    public SimpleExerciseViewModel(String number, String topic, boolean completed) {
        this.number.set(number);
        this.topic.set(topic);
        this.completed.set(completed);
    }

    public StringProperty getNumberProperty()          { return number; }
    public StringProperty getTopicProperty()           { return topic; }
    public ObjectProperty<Boolean> getCompletedProperty() { return completed; }

    public String getNumber()    { return number.get(); }
    public String getTopic()     { return topic.get(); }
    public Boolean isCompleted() { return completed.get(); }

    public void setNumber(String number)       { this.number.set(number); }
    public void setTopic(String topic)         { this.topic.set(topic); }
    public void setCompleted(boolean completed){ this.completed.set(completed); }
}
